"""Top-level orchestration: config, aliases, rewrite, parse, resolve, validate, run."""

import os
import sys
import time

from . import config_loader
from .arguments import END_OF_OPTIONS, is_assoc_token, parse_argv
from .commands import build_command_tree
from .context import Context
from .errors import AppctlError, MultiLineError, UsageError
from .file_cache import get_cache
from .help import render_root_help, render_usage
from .logger import FileLogger, log_path
from .output import Output
from .remote import run_remote
from .resolver import resolve
from .rewrites import apply_rewrites
from .runtime_config import build_runtime_config, deprecation_warnings, is_strict_mode
from .suggest import get_suggestion
from .validator import ArgumentValidator


def extract_alias(argv):
    """Return ``(alias, argv_without_alias)``; the alias is the first non-flag token."""
    for index, token in enumerate(argv):
        if token == END_OF_OPTIONS:
            break
        if is_assoc_token(token):
            continue
        if config_loader.is_alias(token):
            return token, argv[:index] + argv[index + 1:]
        break
    return None, list(argv)


def _unique(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return seen


def check_disabled(command, typed, disabled):
    """Raise if the command or one of its parents is disabled."""
    disabled = {" ".join(str(entry).split()) for entry in disabled}
    for path in (command.path, typed[:len(command.path)]):
        for depth in range(1, len(path) + 1):
            name = " ".join(path[:depth])
            if name in disabled:
                raise AppctlError(f"The '{name}' command has been disabled.")


def guarded(output, action, *args):
    """Run ``action`` and report user-facing errors; return the exit code."""
    try:
        return int(action(*args) or 0)
    except UsageError as exc:
        output.line(exc.usage)
        return exc.exit_code
    except MultiLineError as exc:
        output.error_multi_line(exc.lines, sensitive=exc.sensitive)
        return exc.exit_code
    except AppctlError as exc:
        output.error(exc.message, sensitive=exc.sensitive)
        return exc.exit_code


def is_completion_request(positional):
    """Tab completion runs ``cli completions``; it is never logged."""
    return list(positional[:2]) == ["cli", "completions"]


class Runner:
    def __init__(self, argv, parsed, environ, output, strict, loaded):
        self.argv = argv
        self.parsed = parsed
        self.environ = environ
        self.output = output
        self.strict = strict
        self.loaded = loaded
        self._root = None

    @property
    def root(self):
        if self._root is None:
            self._root = build_command_tree()
        return self._root

    # -- aliases ----------------------------------------------------------

    def run_alias(self, name, stack=()):
        aliases = self.loaded.aliases
        if name == config_loader.ALL_ALIAS and not aliases:
            raise AppctlError("Cannot use '@all' when no aliases are registered.")
        if name not in aliases:
            message = f"Alias '{name}' not found."
            suggestion = get_suggestion(name, list(aliases))
            if suggestion:
                message += f"\nDid you mean '{suggestion}'?"
            raise AppctlError(message)
        definition = aliases[name]
        if name == config_loader.ALL_ALIAS and definition is None:
            members = sorted((a for a, d in aliases.items() if a != name and not isinstance(d, list)),
                             key=config_loader.alias_sort_key)
            return self.run_group(name, members, stack)
        if isinstance(definition, list):
            members = _unique(definition)
            invalid = [m for m in members if m not in aliases]
            if invalid:
                raise AppctlError(
                    f"Group '{name}' contains one or more invalid aliases: {', '.join(invalid)}."
                )
            return self.run_group(name, members, stack)
        return self.run(name, definition if isinstance(definition, dict) else {})

    def run_group(self, name, members, stack):
        stack = stack + (name,)
        result = 0
        for member in members:
            if member in stack:
                continue
            self.output.log(member)
            self.output.stdout.flush()
            code = guarded(self.output, self.run_alias, member, stack)
            self.output.stdout.flush()
            if code:
                result = code
        return result

    # -- a single execution ----------------------------------------------

    def run(self, alias=None, alias_params=None):
        runtime = build_runtime_config(self.parsed.runtime, self.loaded.merged, alias_params)
        self.output.set_color(runtime.get("color"))
        if runtime.get("ssh"):
            return run_remote(runtime["ssh"], self.argv, self.environ, self.output,
                              alias=alias, alias_params=alias_params,
                              skip_tty=bool(runtime.get("skip-tty")))
        positional = self.parsed.positional
        if not positional:
            self.output.line(render_root_help(self.root))
            return 0
        command, remaining = resolve(self.root, positional)
        check_disabled(command, positional, runtime["disabled_commands"])
        if not command.is_runnable:
            self.output.line(render_usage(command))
            return 0
        self.output.debug(f"Running command: {command.full_name}")
        args, assoc = ArgumentValidator(command).validate(
            remaining, self.parsed.assoc, warn=self.output.warning,
            read_stdin=self.output.read_stdin,
        )
        context = Context(root=self.root, command=command, output=self.output,
                          runtime=runtime, strict=self.strict, config=self.loaded,
                          alias=alias)
        return command.handler(context, args, assoc)


def main(argv=None, environ=None, stdout=None, stderr=None, cwd=None, stdin=None):
    started = time.monotonic()
    argv = sys.argv[1:] if argv is None else list(argv)
    environ = os.environ if environ is None else environ
    strict = is_strict_mode(environ)

    invocation = list(argv)
    alias, argv = extract_alias(argv)
    parsed = parse_argv(apply_rewrites(argv), strict=strict)
    logger = FileLogger(log_path(config_loader.root_dir(environ)),
                        enabled=not is_completion_request(parsed.positional))
    logger.start_invocation(invocation)
    output = Output(quiet=bool(parsed.runtime.get("quiet")), debug=parsed.runtime.get("debug", False),
                    stdout=stdout, stderr=stderr, stdin=stdin,
                    color=parsed.runtime.get("color", "auto"), logger=logger, start_time=started)
    for warning in deprecation_warnings(parsed.runtime):
        print(warning, file=output.stderr)

    def start():
        loaded = config_loader.load(environ, cwd)
        output.set_color(build_runtime_config(parsed.runtime, loaded.merged)["color"])
        output.debug(f"Using global config: {loaded.global_path}", group="bootstrap")
        if loaded.project_path:
            output.debug(f"Using project config: {loaded.project_path}", group="bootstrap")
        else:
            output.debug("No project config found.", group="bootstrap")
        runner = Runner(argv, parsed, environ, output, strict, loaded)
        if alias:
            return runner.run_alias(alias)
        return runner.run()

    code = guarded(output, start)
    if not is_completion_request(parsed.positional):
        clean_cache(environ, output)
    return code


def clean_cache(environ, output):
    """Deterministic end-of-invocation cache cleanup (expiry, then LRU size limit)."""
    try:
        get_cache(environ, output).clean()
    except Exception:  # cleanup must never affect the command's outcome
        pass
"""Loading of global/project YAML config files and alias definitions."""

import json
import os
import re
from dataclasses import dataclass, field

import yaml

from .errors import AppctlError

CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"
ROOT_DIR_ENV = "APPCTL_ROOT_DIR"
PACKAGES_DIR_ENV = "APPCTL_PACKAGES_DIR"
RUNTIME_ALIAS_ENV = "APPCTL_RUNTIME_ALIAS"

PROJECT_CONFIG_FILES = ("appctl.local.yml", "appctl.yml")
ALIAS_RE = re.compile(r"^@[A-Za-z0-9_.\-]+$")
ALL_ALIAS = "@all"
META_KEY = "_"

# Keys the global config file must always define, with their defaults.
REQUIRED_GLOBAL_KEYS = (("locale", "en_US"), ("installer_version", "stable"))


def is_alias(name):
    return isinstance(name, str) and bool(ALIAS_RE.match(name))


def alias_sort_key(name):
    return (name.lower(), name)


# -- locations -----------------------------------------------------------


def root_dir(environ):
    value = environ.get(ROOT_DIR_ENV)
    if value:
        return value
    return os.path.join(os.path.expanduser("~"), ".appctl")


def global_config_path(environ):
    value = environ.get(CONFIG_PATH_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "config", "config.yml")


def packages_dir(environ):
    value = environ.get(PACKAGES_DIR_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "packages")


def find_project_config(cwd):
    """Search upward from ``cwd``; the first directory with a config wins."""
    directory = os.path.abspath(cwd)
    while True:
        for name in PROJECT_CONFIG_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


# -- auto-creation ---------------------------------------------------------


def _read_mapping(path):
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise AppctlError(f"Unable to parse the config file '{path}': {exc}") from exc
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise AppctlError(f"The config file '{path}' must contain a YAML mapping.")
    return data, text


def ensure_global_config(path, strict=True):
    """Add missing required keys to the global config file, creating it.

    Write failures raise :class:`AppctlError` unless ``strict`` is false.
    """
    try:
        if os.path.exists(path):
            data, text = _read_mapping(path)
        else:
            data, text = {}, ""
        missing = [(k, v) for k, v in REQUIRED_GLOBAL_KEYS if k not in data]
        if not missing:
            return
        if text and not text.endswith("\n"):
            text += "\n"
        text += "".join(f"{key}: {value}\n" for key, value in missing)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(text)
    except OSError as exc:
        if strict:
            reason = exc.strerror or str(exc)
            raise AppctlError(f"Unable to write the config file '{path}': {reason}.") from exc


# -- YAML loading with inheritance -------------------------------------------


def _merge(base, override, append_arrays):
    """Overlay ``override`` on ``base``; nested mappings merge recursively."""
    if isinstance(base, dict) and isinstance(override, dict):
        merged = dict(base)
        for key, value in override.items():
            merged[key] = _merge(base[key], value, append_arrays) if key in base else value
        return merged
    if append_arrays and isinstance(base, list) and isinstance(override, list):
        return base + override
    return override


def _absolutize_alias_paths(data, directory):
    for key, value in data.items():
        if is_alias(key) and isinstance(value, dict):
            path = value.get("path")
            if isinstance(path, str) and path and "ssh" not in value:
                value["path"] = os.path.normpath(os.path.join(directory, os.path.expanduser(path)))


def load_config_file(path, accumulated=None, _seen=None):
    """Merge the YAML file at ``path`` (and its ancestors) over ``accumulated``."""
    accumulated = dict(accumulated or {})
    if not path:
        return accumulated
    path = os.path.abspath(path)
    seen = set(_seen or ())
    if path in seen or not os.path.isfile(path):
        return accumulated
    seen.add(path)
    try:
        data, _ = _read_mapping(path)
    except OSError:
        return accumulated
    directory = os.path.dirname(path)
    meta = data.pop(META_KEY, None)
    meta = meta if isinstance(meta, dict) else {}
    inherit = meta.get("inherit")
    if isinstance(inherit, str) and inherit:
        base = os.path.join(directory, os.path.expanduser(inherit))
        accumulated = load_config_file(base, accumulated, seen)
    _absolutize_alias_paths(data, directory)
    return _merge(accumulated, data, meta.get("merge") is True)


# -- aliases -------------------------------------------------------------------


def runtime_aliases(environ, cwd):
    raw = environ.get(RUNTIME_ALIAS_ENV)
    if not raw:
        return {}
    try:
        decoded = json.loads(raw)
    except ValueError:
        return {}
    if not isinstance(decoded, dict):
        return {}
    aliases = {k: v for k, v in decoded.items() if is_alias(k)}
    _absolutize_alias_paths(aliases, cwd)
    return aliases


def collect_aliases(config, extra=None):
    """Return ``{name: definition}``, registering ``@all`` when needed.

    A definition is either a mapping of connection parameters or a list
    of alias names (a group).
    """
    aliases = {}
    for key, value in list(config.items()) + list((extra or {}).items()):
        if not is_alias(key):
            continue
        if isinstance(value, list):
            aliases[key] = [str(v) for v in value]
        elif isinstance(value, dict):
            aliases[key] = dict(value)
        elif value is None:
            aliases[key] = {}
        else:
            aliases[key] = value
    if aliases and ALL_ALIAS not in aliases:
        aliases[ALL_ALIAS] = None  # implicit: every registered alias
    return aliases


# -- entry point ---------------------------------------------------------------


@dataclass
class LoadedConfig:
    global_path: str = None
    project_path: str = None
    global_config: dict = field(default_factory=dict)
    merged: dict = field(default_factory=dict)
    aliases: dict = field(default_factory=dict)
    packages_dir: str = None


def load(environ, cwd=None):
    cwd = cwd or os.getcwd()
    global_path = global_config_path(environ)
    explicit = bool(environ.get(CONFIG_PATH_ENV) or environ.get(ROOT_DIR_ENV))
    ensure_global_config(global_path, strict=explicit)
    global_config = load_config_file(global_path)
    project_path = find_project_config(cwd)
    if project_path and os.path.abspath(project_path) == os.path.abspath(global_path):
        project_path = None
    merged = load_config_file(project_path, global_config)
    return LoadedConfig(
        global_path=global_path,
        project_path=project_path,
        global_config=global_config,
        merged=merged,
        aliases=collect_aliases(merged, runtime_aliases(environ, cwd)),
        packages_dir=packages_dir(environ),
    )
"""``appctl option``: retrieve and set options (simulated)."""

import fnmatch

from ..errors import AppctlError
from ..formatter import format_value
from ._listing import LIST_OPTIONS, render_list

OPTIONS = [
    {"option_name": "admin_email", "option_value": "admin@example.test", "autoload": "yes"},
    {"option_name": "blogname", "option_value": "My Application", "autoload": "yes"},
    {"option_name": "home", "option_value": "https://example.test", "autoload": "yes"},
    {"option_name": "siteurl", "option_value": "https://example.test", "autoload": "yes"},
    {"option_name": "timezone_string", "option_value": "UTC", "autoload": "no"},
]
FIELDS = ["option_name", "option_value", "autoload"]


def _find(key):
    return next((o for o in OPTIONS if o["option_name"] == key), None)


def add(ctx, args, assoc):
    key, value = args
    if _find(key):
        raise AppctlError(f"Could not add option '{key}'. Does it already exist?")
    ctx.output.success(f"Added '{key}' option (autoload: {assoc['autoload']}).")


def delete(ctx, args, assoc):
    for key in args:
        if _find(key):
            ctx.output.success(f"Deleted '{key}' option.")
        else:
            ctx.output.warning(f"Could not delete '{key}' option. Does it exist?")


def get(ctx, args, assoc):
    option = _find(args[0])
    if option is None:
        raise AppctlError(f"Could not get '{args[0]}' option. Does it exist?")
    ctx.output.line(format_value(option["option_value"], assoc["format"]))


def list_(ctx, args, assoc):
    items = OPTIONS
    pattern = assoc.get("search")
    if pattern and pattern is not True:
        items = [o for o in items if fnmatch.fnmatchcase(o["option_name"], pattern)]
    autoload = assoc.get("autoload")
    if autoload in ("on", "off", "yes", "no"):
        wanted = "yes" if autoload in ("on", "yes") else "no"
        items = [o for o in items if o["autoload"] == wanted]
    filters = {k: v for k, v in assoc.items() if k not in ("search", "autoload")}
    render_list(ctx, items, filters, ["option_name", "option_value"], FIELDS,
                id_field="option_name", prefix="option")


def update(ctx, args, assoc):
    key, value = args
    option = _find(key)
    if option and option["option_value"] == value:
        ctx.output.success(f"Value passed for '{key}' option is unchanged.")
    elif option:
        ctx.output.success(f"Updated '{key}' option.")
    else:
        ctx.output.success(f"Added '{key}' option.")


def register(registry):
    registry.add("option", description="Retrieves and sets options, including plugin and theme settings.")
    value_options = {
        "key": "The name of the option.",
        "value": "The value of the option.",
        "format": "The serialization format for the value (plaintext, json).",
        "autoload": "Should this option be automatically loaded (yes, no).",
    }
    registry.add(
        "option add", add,
        synopsis="<key> [<value>] [--format=<format>] [--autoload=<autoload>]",
        description="Adds a new option value.",
        defaults={"value": "", "format": "plaintext", "autoload": "yes"},
        options=value_options,
    )
    registry.add(
        "option delete", delete,
        synopsis="<key>...",
        description="Deletes an option.",
        options={"key": "Key for the option."},
    )
    registry.add(
        "option get", get,
        synopsis="<key> [--format=<format>]",
        description="Gets the value for an option.",
        defaults={"format": "plaintext"},
        options=value_options,
    )
    registry.add(
        "option list", list_,
        synopsis="[--search=<pattern>] [--autoload=<value>] [--field=<field>] "
                 "[--fields=<fields>] [--format=<format>]",
        description="Lists options and their values.",
        defaults={"format": "table"},
        options=dict(LIST_OPTIONS, search="Use wildcards ( * and ? ) to match option name.",
                     autoload="Match only autoload options when value is on, and only "
                              "not-autoload options when off."),
    )
    registry.add(
        "option update", update,
        synopsis="<key> [<value>] [--autoload=<autoload>] [--format=<format>]",
        description="Updates an option value.",
        alias="set",
        defaults={"value": "", "format": "plaintext"},
        options=value_options,
    )
"""``appctl db``: basic database operations (simulated)."""

from ._listing import confirm

DATABASE = "appctl"
TABLES = ["app_comments", "app_options", "app_posts", "app_sites", "app_users"]


def create(ctx, args, assoc):
    ctx.output.success("Database created.")


def drop(ctx, args, assoc):
    if not confirm(ctx, assoc, f"Are you sure you want to drop the '{DATABASE}' database?"):
        return
    ctx.output.success(f"Database '{DATABASE}' dropped.")


def reset(ctx, args, assoc):
    if not confirm(ctx, assoc, f"Are you sure you want to reset the '{DATABASE}' database?"):
        return
    ctx.output.success(f"Database '{DATABASE}' reset.")


def export(ctx, args, assoc):
    tables = assoc.get("tables")
    scope = f" (tables: {tables})" if tables and tables is not True else ""
    if assoc.get("porcelain"):
        ctx.output.line(args[0])
        return
    ctx.output.success(f"Exported to '{args[0]}'{scope}.")


def import_(ctx, args, assoc):
    ctx.output.success(f"Imported from '{args[0]}'.")


def query(ctx, args, assoc):
    sql = args[0] if args else ""
    ctx.output.success(f"Executed query: {sql}" if sql else "Opened an interactive query session.")


def tables(ctx, args, assoc):
    wanted = [t for t in TABLES if not args or t in args]
    if assoc["format"] == "csv":
        ctx.output.line(",".join(wanted))
    else:
        for name in wanted:
            ctx.output.line(name)


def check(ctx, args, assoc):
